import React, { useState } from "react";
import "./Upload.css";
import "./Feedback.css";

function UploadAndFeedback() {
  const [videoFile, setVideoFile] = useState(null);
  const [feedback, setFeedback] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleFileChange = (event) => {
    setVideoFile(event.target.files[0]);
    setFeedback(null); // Reset feedback when new file is chosen
  };

  const handleAnalyze = async () => {
    if (!videoFile) {
      alert("Please upload a video first.");
      return;
    }

    const formData = new FormData();
    formData.append("video", videoFile);
    setLoading(true);

    try {
      const response = await fetch("http://localhost:5000/transcribe", {
        method: "POST",
        body: formData,
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Error processing video.");
      }

      setFeedback(data);
    } catch (error) {
      console.error("Error analyzing video:", error);
      setFeedback({
        transcript: "Error processing video. Please try again.",
        ai_feedback: "",
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container">
      <div className="upload-content">
        <div className="video-section">
          <h1>Upload your video</h1>
          <input type="file" accept="video/*" onChange={handleFileChange} />
          {videoFile && (
            <video controls>
              <source src={URL.createObjectURL(videoFile)} type={videoFile.type} />
              Your browser does not support the video tag.
            </video>
          )}
          <button onClick={handleAnalyze} disabled={loading}>
            {loading ? "Analyzing..." : "Analyze Video"}
          </button>
        </div>

        {/* FEEDBACK SECTION */}
        {feedback && (
          <div className="feedback-container">
            <h1 className="feedback-title">JagCoach Feedback</h1>
            <p className="feedback-subtitle">Here is an analysis of your oral presentation:</p>

            {/* Transcript */}
            {feedback.transcript && (
              <div className="feedback-box">
                <h2>Speech Transcript</h2>
                <p className="transcript-text">{feedback.transcript}</p>
              </div>
            )}

            {/* Analysis */}
            <div className="feedback-box">
              <h2>Speech Analysis</h2>
              <p><strong>Speech Rate:</strong> {feedback.speech_rate_wps} words/sec</p>
              <p><strong>Number of Pauses:</strong> {feedback.num_pauses}</p>
              <p><strong>Total Silence:</strong> {feedback.total_silence_sec} sec</p>
              <p><strong>Average Pitch:</strong> {feedback.average_pitch} Hz</p>
              <p><strong>Eye Contact Ratio:</strong> {feedback.eye_contact_ratio}</p>
              <p><strong>Emotion Summary:</strong> {feedback.emotion_summary?.map(([e, c]) => `${e} (${c})`).join(", ")}</p>
            </div>

            {/* AI Feedback */}
            {feedback.ai_feedback && (
              <div className="feedback-box ai-feedback">
                <h2>AI Feedback</h2>
                <div
                  className="ai-feedback-text"
                  dangerouslySetInnerHTML={{
                    __html: feedback.ai_feedback
                      .replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>")
                      .replace(/(?:\r\n|\r|\n)/g, "<br><br>")
                      .replace(/- /g, "<br>• ")
                  }}
                />
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default UploadAndFeedback;
